// Block (composition) — a responsive list of active device sessions and revoke actions.
// Card owns row chrome; Badge/Button own status and action look; Stack owns arrangement.
import type { Ref } from "react";
import { Badge } from "../components/Badge";
import { Button } from "../components/Button";
import { Card } from "../components/Card";
import { Stack } from "../layouts/Stack";
import { SkeletonList } from "./SkeletonList";
import "./SessionsList.css";

export interface SessionsListProps {
  sessions: {
    id: string;
    device: string;
    location?: string;
    lastActive?: string;
    current?: boolean;
  }[];
  onRevoke?: (id: string) => void;
  /** Renders skeleton placeholders while sessions are loading. */
  isLoading?: boolean;
  /** Message shown when there are no active sessions. */
  emptyLabel?: string;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function SessionsList({
  sessions,
  onRevoke,
  isLoading,
  emptyLabel = "No active sessions",
  className,
  ref,
}: SessionsListProps) {
  if (isLoading) {
    return <SkeletonList rows={3} className={className} />;
  }
  if (sessions.length === 0) {
    return (
      <p role="status" className={`sd-sessionslist__empty sd-type-caption-medium${className ? ` ${className}` : ""}`}>
        {emptyLabel}
      </p>
    );
  }
  return (
    <Stack
      as="section"
      ref={ref}
      aria-label="Active sessions"
      gap="small"
      className={className ? `sd-sessionslist ${className}` : "sd-sessionslist"}
    >
      {sessions.map((session) => (
        <Card key={session.id} className="sd-sessionslist__row">
          <Stack
            direction={{ small: "column", medium: "row" }}
            justify="between"
            align={{ small: "stretch", medium: "center" }}
            gap="small"
            className="sd-sessionslist__content"
          >
            <Stack gap="x-small" className="sd-sessionslist__details">
              <Stack direction="row" align="center" gap="x-small" wrap className="sd-sessionslist__head">
                <>
                  <h3 className="sd-sessionslist__device sd-type-title-medium">{session.device}</h3>
                </>
                {session.current && <Badge>This device</Badge>}
              </Stack>
              {(session.location || session.lastActive) && (
                <>
                  <span className="sd-sessionslist__metadata sd-type-caption-medium">
                    {[session.location, session.lastActive].filter(Boolean).join(" · ")}
                  </span>
                </>
              )}
            </Stack>
            <Button
              type="button"
              variant="secondary"
              size="small"
              isDisabled={session.current}
              aria-label={`Revoke session on ${session.device}`}
              onPress={() => onRevoke?.(session.id)}
            >
              Revoke
            </Button>
          </Stack>
        </Card>
      ))}
    </Stack>
  );
}

/* SessionsList.css — .sd-sessionslist (Block)
   Arrangement only: rows fill the region and metadata can shrink without overflow. */
.sd-sessionslist {
  width: 100%;
}

.sd-sessionslist__row,
.sd-sessionslist__details {
  min-width: 0;
}

.sd-sessionslist__device {
  margin: 0;
}

.sd-sessionslist__metadata {
  overflow-wrap: anywhere;
}

/* empty state — layout only (muted color inherits default; blocks own no color) */
.sd-sessionslist__empty {
  padding: var(--sd-space-large);
  text-align: center;
}
